package edu.niu.android.smartstudyplanner.data.entities;

import androidx.room.Entity;
import androidx.room.ForeignKey;
import androidx.room.Index;
import androidx.room.PrimaryKey;

@Entity(
        tableName = "flashcards",
        foreignKeys = @ForeignKey(
                entity = Course.class,
                parentColumns = "id",
                childColumns = "courseId",
                onDelete = ForeignKey.CASCADE
        ),
        indices = {@Index("courseId")}
)
public class Flashcard {

    // Auto generated primary key assigned by Room on insert.
    @PrimaryKey(autoGenerate = true)
    private long id;

    // ID of the course this card belongs to.
    private long courseId;

    // Question or term shown on the front of the card.
    private String front;

    // Answer or definition shown on the back of the card.
    private String back;

    // True once the student marks this card as known.
    private boolean mastered;

    // How many times this card has been flipped/reviewed.
    private int reviewCount;

    // Timestamp (millis) when the card was created.
    private long createdAt;

    /**
     * Builds a new flashcard. New cards start as not mastered with a zero
     * review count; the id is auto generated by Room on insert.
     */
    public Flashcard(long courseId, String front, String back, long createdAt) {
        this.courseId = courseId;
        this.front = front;
        this.back = back;
        this.mastered = false;
        this.reviewCount = 0;
        this.createdAt = createdAt;
    }

    // Standard getters and setters used by Room and the UI.

    public long getId() { return id; }
    public void setId(long id) { this.id = id; }

    public long getCourseId() { return courseId; }
    public void setCourseId(long courseId) { this.courseId = courseId; }

    public String getFront() { return front; }
    public void setFront(String front) { this.front = front; }

    public String getBack() { return back; }
    public void setBack(String back) { this.back = back; }

    public boolean isMastered() { return mastered; }
    public void setMastered(boolean mastered) { this.mastered = mastered; }

    public int getReviewCount() { return reviewCount; }
    public void setReviewCount(int reviewCount) { this.reviewCount = reviewCount; }

    public long getCreatedAt() { return createdAt; }
    public void setCreatedAt(long createdAt) { this.createdAt = createdAt; }
}